const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function denseEdgeFamilyPresentation(input, reducedMotion = false, reducedFlash = false) { const crowd = clamp01(input.crowd), protectedContour = input.family === 'safeLane' || input.bossProtected || (input.family === 'projectile' && input.critical), floor = input.family === 'safeLane' ? 1 : protectedContour ? .975 : input.critical ? .955 : input.family === 'impact' ? .91 : input.family === 'hazard' ? .92 : input.family === 'specialist' ? .925 : .94, yieldRate = input.family === 'safeLane' ? 0 : protectedContour ? .025 : input.critical ? .045 : 1 - floor, accessibility = (reducedMotion ? .998 : 1) * (reducedFlash ? .998 : 1); return { canonicalContourScale: 1, secondaryContourScale: input.family === 'safeLane' ? 1 : Math.max(floor, 1 - crowd * yieldRate) * accessibility, protectedContour, presentationOnly: true }; }
export function denseEdgeBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), stress = clamp01(clamp01(input.crowd) * .78 + critical * .18 + (input.bossActive ? .04 : 0)), strongSecondaryLimit = stress >= .76 ? 1 : stress >= .46 ? 2 : 3, accessibility = (reducedMotion ? .998 : 1) * (reducedFlash ? .998 : 1); return { stress, strongSecondaryLimit, canonicalContourScale: 1, secondaryContourScale: Math.max(.91, 1 - stress * .09) * accessibility, safeLaneContourScale: 1, presentationOnly: true }; }
